export default RunningAverage;
declare class RunningAverage {
    /**
     * @param {number} windowSize - number of points to average
     */
    constructor(windowSize: number);
    windowSize: number;
    samples: any[];
    sampleIndex: number;
    total: number;
    numSamples: number;
    /**
     * Clear the running average.
     * @public
     */
    public clear(): void;
    /**
     * Gets the current value of the running average.
     * @public
     *
     * @returns {number}
     */
    public getRunningAverage(): number;
    /**
     * Returns whether the number of samples is at least as large as the self size (the buffer is full).
     * @public
     *
     * @returns {boolean}
     */
    public isSaturated(): boolean;
    /**
     * Add a data point to the average and return the new running average.
     * @public
     *
     * @param {number} sample
     * @returns {number}
     */
    public updateRunningAverage(sample: number): number;
}
